extension AppDelegate {
 @objc func newRDPSession(){rdpForm(index:nil)}
 func rdpForm(index:Int?){let old=index.map{sessions[$0]} ?? Session(name:"",host:"",user:"",port:3389,key:"",connectionTimeout:15,id:UUID(),group:sessionBrowser.selectedGroup,kind:.rdp,rdp:RDPSettings());guard let value=RDPEditor(session:old).run() else{return};let before=sessions;if let index=index{sessions[index]=value}else{sessions.append(value)};if !persist(){sessions=before;sessionBrowser.reload(sessions)}}
 func openRDP(_ input:Session){do{var session=try input.validatedRDP();guard let entered=RDPCredentials.ask(session) else{return};let credentials=try entered.validated();session.user=credentials.user;session.rdp?.domain=credentials.domain;_ = recordRecent(input);let item=NSTabViewItem(identifier:UUID().uuidString);item.label=session.name;item.view=RDPWorkspace(session:session,password:credentials.password);tabs.addTabViewItem(item);tabs.selectTabViewItem(item);updateTabStrip()}catch{alert(error.localizedDescription)}}
 func reconnectRDP(_ item:NSTabViewItem,_ old:RDPWorkspace){guard let entered=RDPCredentials.ask(old.session) else{return};do{let credentials=try entered.validated();var session=old.session;session.user=credentials.user;session.rdp?.domain=credentials.domain;old.stop();item.view=RDPWorkspace(session:session,password:credentials.password);updateTabStrip()}catch{alert(error.localizedDescription)}}
}
